script:
/* italic-free serif; Fraunces + Karla pairing */
html { scroll-behavior: smooth; }
::selection { background: #B9673F; color: #FFFFFF; }

html.al-js .al-rise { opacity: 0; transform: translateY(18px); }
html.al-js .al-rise.al-in {
  opacity: 1; transform: none;
  transition: opacity 0.9s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.9s cubic-bezier(0.22, 1, 0.36, 1);
}
html.al-js .al-d1.al-in { transition-delay: 0.13s; }
html.al-js .al-d2.al-in { transition-delay: 0.26s; }

.al-grow { flex-grow: 1; flex-shrink: 1; min-width: 0; }

.al-ul {
  background-image: linear-gradient(currentColor, currentColor);
  background-position: left bottom; background-repeat: no-repeat;
  background-size: 0% 1.5px;
  transition: background-size 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}
.al-ul:hover { background-size: 100% 1.5px; }

.al-btn { transition: transform 0.25s ease, box-shadow 0.25s ease,
  filter 0.25s ease; }
.al-btn:hover { transform: translateY(-2px); filter: brightness(1.05);
  box-shadow: 0 12px 26px rgba(185, 103, 63, 0.3); }
.al-btn-o { transition: background-color 0.25s ease, color 0.25s ease,
  transform 0.25s ease; }
.al-btn-o:hover { background-color: #2D2823; color: #F6F2EC;
  transform: translateY(-2px); }
.al-btn-d { transition: background-color 0.25s ease, transform 0.25s
  ease; }
.al-btn-d:hover { background-color: rgba(246, 242, 236, 0.1);
  transform: translateY(-2px); }

.al-card { transition: transform 0.35s cubic-bezier(0.22, 1, 0.36, 1),
  box-shadow 0.35s ease, border-color 0.35s ease; }
.al-card:hover { transform: translateY(-4px);
  box-shadow: 0 18px 40px rgba(45, 40, 35, 0.08); }
.al-cond:hover { border-color: #B9673F; }
.al-cond .al-arrow { transition: letter-spacing 0.3s ease; }
.al-cond:hover .al-arrow { letter-spacing: 0.03em; }

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
}
